<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ブロック崩し</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0f0f1a;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    font-family: "Segoe UI", "Hiragino Sans", "Meiryo", sans-serif;
    color: #eee;
    user-select: none;
  }
  h1 {
    font-size: 22px;
    letter-spacing: 4px;
    margin: 14px 0 8px;
    color: #7dd3fc;
    text-shadow: 0 0 12px rgba(125, 211, 252, .5);
  }
  #wrap { position: relative; }
  canvas {
    background: linear-gradient(#101024, #181830);
    border: 2px solid #2c2c4a;
    border-radius: 8px;
    box-shadow: 0 0 40px rgba(80, 120, 255, .15);
    display: block;
  }
  #hud {
    display: flex;
    justify-content: space-between;
    width: 640px;
    margin: 10px 2px 6px;
    font-size: 14px;
    color: #9aa0c0;
  }
  #hud b { color: #fff; font-variant-numeric: tabular-nums; }
  #overlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    background: rgba(8, 8, 18, .72);
    border-radius: 8px;
    backdrop-filter: blur(3px);
  }
  #overlay.hidden { display: none; }
  #overlay .title { font-size: 34px; font-weight: 700; letter-spacing: 6px; }
  #overlay .sub { font-size: 14px; color: #9aa0c0; line-height: 1.8; text-align: center; }
  #overlay button {
    font-size: 16px;
    padding: 10px 34px;
    border: none;
    border-radius: 6px;
    background: #38bdf8;
    color: #06202e;
    font-weight: 700;
    cursor: pointer;
    letter-spacing: 2px;
    transition: transform .1s, box-shadow .2s;
    box-shadow: 0 0 18px rgba(56, 189, 248, .4);
  }
  #overlay button:hover { transform: scale(1.06); box-shadow: 0 0 26px rgba(56, 189, 248, .7); }
  #tips { margin-top: 8px; font-size: 12px; color: #565c7c; }
</style>
</head>
<body>
<h1>BREAKOUT</h1>
<div id="hud">
  <span>SCORE <b id="score">0</b></span>
  <span>HIGH <b id="high">0</b></span>
  <span>LEVEL <b id="level">1</b></span>
  <span>LIVES <b id="lives">3</b></span>
  <span>COMBO <b id="combo">0</b></span>
</div>
<div id="wrap">
  <canvas id="game" width="640" height="480"></canvas>
  <div id="overlay">
    <div class="title" id="ov-title">BREAKOUT</div>
    <div class="sub" id="ov-sub">マウス ← → または A/D キーでパドルを操作<br>ボールを当ててブロックを全て壊そう</div>
    <button id="ov-btn">スタート</button>
  </div>
</div>
<div id="tips">マウス移動 / ←→ / A・D ： パドル移動　・　スペース ： ボール発射・一時停止</div>

<script>
(() => {
  const cvs = document.getElementById('game');
  const ctx = cvs.getContext('2d');
  const W = cvs.width, H = cvs.height;

  const ui = {
    score: document.getElementById('score'),
    high: document.getElementById('high'),
    level: document.getElementById('level'),
    lives: document.getElementById('lives'),
    combo: document.getElementById('combo'),
    overlay: document.getElementById('overlay'),
    title: document.getElementById('ov-title'),
    sub: document.getElementById('ov-sub'),
    btn: document.getElementById('ov-btn'),
  };

  // ---- 定数 ----
  const PADDLE_W0 = 96, PADDLE_H = 12, PADDLE_Y = H - 34;
  const BALL_R = 7;
  const BRICK_COLS = 10, BRICK_TOP = 50, BRICK_GAP = 4;
  const BRICK_MARGIN = 20;
  const BRICK_W = (W - BRICK_MARGIN * 2 - BRICK_GAP * (BRICK_COLS - 1)) / BRICK_COLS;
  const BRICK_H = 20;

  const ROW_COLORS = ['#f87171', '#fb923c', '#facc15', '#4ade80', '#38bdf8', '#a78bfa'];

  // ---- 状態 ----
  let state = 'menu'; // menu | ready | play | pause | levelup | over | win
  let score = 0, lives = 3, level = 1, combo = 0, comboTimer = 0;
  let high = Number(localStorage.getItem('bb_high') || 0);
  ui.high.textContent = high;

  const paddle = { x: W / 2 - PADDLE_W0 / 2, w: PADDLE_W0, vx: 0 };
  const ball = { x: 0, y: 0, vx: 0, vy: 0, stuck: true };
  let bricks = [];
  let particles = [];
  let powerups = [];
  let paddleWideTimer = 0;

  const keys = {};

  function levelConfig(lv) {
    const rows = Math.min(4 + lv, ROW_COLORS.length);
    const speed = 4 + lv * 0.5;
    return { rows, speed };
  }

  function buildBricks() {
    const { rows } = levelConfig(level);
    bricks = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < BRICK_COLS; c++) {
        const hp = (level >= 3 && r < 2) ? 2 : 1; // 上位レベルでは上2列が頑丈
        bricks.push({
          x: BRICK_MARGIN + c * (BRICK_W + BRICK_GAP),
          y: BRICK_TOP + r * (BRICK_H + BRICK_GAP),
          w: BRICK_W, h: BRICK_H,
          color: ROW_COLORS[r % ROW_COLORS.length],
          hp, maxHp: hp,
        });
      }
    }
  }

  function resetBall() {
    ball.stuck = true;
    ball.x = paddle.x + paddle.w / 2;
    ball.y = PADDLE_Y - BALL_R - 1;
    ball.vx = 0; ball.vy = 0;
    powerups = [];
    paddleWideTimer = 0;
    setPaddleWidth(PADDLE_W0);
  }

  function launchBall() {
    if (!ball.stuck) return;
    const { speed } = levelConfig(level);
    const angle = (-Math.PI / 2) + (Math.random() * 0.7 - 0.35);
    ball.vx = Math.cos(angle) * speed;
    ball.vy = Math.sin(angle) * speed;
    ball.stuck = false;
  }

  function setPaddleWidth(w) {
    const center = paddle.x + paddle.w / 2;
    paddle.w = w;
    paddle.x = Math.min(W - w, Math.max(0, center - w / 2));
  }

  // ---- 入力 ----
  let mouseX = null;
  cvs.addEventListener('mousemove', e => {
    const rect = cvs.getBoundingClientRect();
    mouseX = (e.clientX - rect.left) * (W / rect.width);
  });
  window.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (e.code === 'Space') {
      e.preventDefault();
      if (state === 'play') {
        if (ball.stuck) launchBall();
        else state = 'pause', showOverlay('PAUSE', 'スペースでもう一度押すと再開', '再開');
      } else if (state === 'pause') hideOverlay(), state = 'play';
    }
    if (e.code === 'Enter' && (state === 'menu' || state === 'over' || state === 'win')) startGame();
  });
  window.addEventListener('keyup', e => keys[e.code] = false);
  ui.btn.addEventListener('click', () => {
    if (state === 'pause') { hideOverlay(); state = 'play'; }
    else startGame();
  });
  cvs.addEventListener('click', () => { if (state === 'play' && ball.stuck) launchBall(); });

  function startGame() {
    score = 0; lives = 3; level = 1; combo = 0;
    buildBricks();
    paddle.x = W / 2 - PADDLE_W0 / 2; setPaddleWidth(PADDLE_W0);
    resetBall();
    hideOverlay();
    state = 'ready';
    updateHud();
    // ready → play（すぐ発射待機）
    state = 'play';
  }

  function showOverlay(title, sub, btn) {
    ui.title.textContent = title;
    ui.sub.innerHTML = sub;
    ui.btn.textContent = btn;
    ui.overlay.classList.remove('hidden');
  }
  function hideOverlay() { ui.overlay.classList.add('hidden'); }

  function updateHud() {
    ui.score.textContent = score;
    ui.high.textContent = high;
    ui.level.textContent = level;
    ui.lives.textContent = lives;
    ui.combo.textContent = combo > 1 ? 'x' + combo : '0';
  }

  // ---- パーティクル ----
  function spawnParticles(x, y, color) {
    for (let i = 0; i < 10; i++) {
      const a = Math.random() * Math.PI * 2, s = 1 + Math.random() * 3;
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: 1, color });
    }
  }

  // ---- パワーアップ ----
  function maybeDropPowerup(x, y) {
    if (Math.random() < 0.12) {
      powerups.push({ x, y, vy: 2, type: Math.random() < 0.5 ? 'wide' : 'life' });
    }
  }

  // ---- 衝突判定（ボール vs ブロック）----
  function hitBrick(b) {
    // どの面から当たったかで反転軸を決める
    const prevX = ball.x - ball.vx, prevY = ball.y - ball.vy;
    const fromSide = prevX < b.x || prevX > b.x + b.w;
    const fromTopBottom = prevY < b.y || prevY > b.y + b.h;

    if (fromTopBottom && !fromSide) {
      ball.vy = -ball.vy;
      ball.y = ball.vy < 0 ? b.y + b.h + BALL_R : b.y - BALL_R;
    } else if (fromSide && !fromTopBottom) {
      ball.vx = -ball.vx;
      ball.x = ball.vx < 0 ? b.x + b.w + BALL_R : b.x - BALL_R;
    } else {
      ball.vx = -ball.vx; ball.vy = -ball.vy;
    }

    b.hp--;
    if (b.hp <= 0) {
      comboTimer = 120;
      combo++;
      score += 10 * level * Math.max(1, combo);
      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color);
      maybeDropPowerup(b.x + b.w / 2, b.y + b.h / 2);
      bricks.splice(bricks.indexOf(b), 1);
    } else {
      score += 5;
    }
    updateHud();
    return true;
  }

  // ---- メインループ ----
  function update() {
    if (state !== 'play') return;

    // パドル移動
    if (mouseX !== null) {
      paddle.x = mouseX - paddle.w / 2;
      mouseX = null;
    }
    const kv = 8;
    if (keys['ArrowLeft'] || keys['KeyA']) paddle.x -= kv;
    if (keys['ArrowRight'] || keys['KeyD']) paddle.x += kv;
    paddle.x = Math.min(W - paddle.w, Math.max(0, paddle.x));

    // パワーアップ消滅タイマー
    if (paddleWideTimer > 0) {
      paddleWideTimer--;
      if (paddleWideTimer === 0) setPaddleWidth(PADDLE_W0);
    }

    // コンボ減衰
    if (comboTimer > 0) { comboTimer--; if (comboTimer === 0) { combo = 0; updateHud(); } }

    // ボール
    if (ball.stuck) {
      ball.x = paddle.x + paddle.w / 2;
      ball.y = PADDLE_Y - BALL_R - 1;
    } else {
      // 1ステップを小分割して高速時の抜けを防ぐ
      const steps = Math.max(1, Math.ceil(Math.hypot(ball.vx, ball.vy) / 4));
      for (let s = 0; s < steps; s++) {
        ball.x += ball.vx / steps;
        ball.y += ball.vy / steps;

        // 壁
        if (ball.x < BALL_R) { ball.x = BALL_R; ball.vx = Math.abs(ball.vx); }
        if (ball.x > W - BALL_R) { ball.x = W - BALL_R; ball.vx = -Math.abs(ball.vx); }
        if (ball.y < BALL_R) { ball.y = BALL_R; ball.vy = Math.abs(ball.vy); }

        // パドル
        if (ball.vy > 0 && ball.y + BALL_R >= PADDLE_Y && ball.y + BALL_R <= PADDLE_Y + PADDLE_H + 6 &&
            ball.x >= paddle.x - BALL_R && ball.x <= paddle.x + paddle.w + BALL_R) {
          const rel = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2); // -1〜1
          const speed = Math.hypot(ball.vx, ball.vy);
          const angle = -Math.PI / 2 + rel * (Math.PI / 3); // 最大60度
          ball.vx = Math.cos(angle) * speed;
          ball.vy = Math.sin(angle) * speed;
          ball.y = PADDLE_Y - BALL_R;
          combo = 0; updateHud();
        }

        // ブロック
        for (const b of bricks) {
          if (ball.x + BALL_R > b.x && ball.x - BALL_R < b.x + b.w &&
              ball.y + BALL_R > b.y && ball.y - BALL_R < b.y + b.h) {
            hitBrick(b);
            break;
          }
        }

        // 落下
        if (ball.y > H + BALL_R * 2) {
          lives--;
          combo = 0;
          updateHud();
          if (lives <= 0) {
            state = 'over';
            if (score > high) { high = score; localStorage.setItem('bb_high', high); }
            showOverlay('GAME OVER', `スコア: ${score}<br>ハイスコア: ${high}`, 'リトライ');
            updateHud();
          } else {
            resetBall();
          }
          break;
        }
      }
    }

    // 全壊 → level up
    if (bricks.length === 0 && state === 'play') {
      if (level >= 8) {
        state = 'win';
        if (score > high) { high = score; localStorage.setItem('bb_high', high); }
        showOverlay('CLEAR!', `全レベル達成！ スコア: ${score}<br>ハイスコア: ${high}`, 'もう一度');
        updateHud();
      } else {
        level++;
        buildBricks();
        resetBall();
        updateHud();
        showOverlay('LEVEL ' + level, 'ブロックが増えた！ スペースで発射', '続ける');
        state = 'levelup';
      }
    }

    // パワーアップ落下
    for (const p of powerups) p.y += p.vy;
    powerups = powerups.filter(p => {
      if (p.y > H) return false;
      if (p.y > PADDLE_Y - 6 && p.y < PADDLE_Y + PADDLE_H + 6 &&
          p.x > paddle.x - 8 && p.x < paddle.x + paddle.w + 8) {
        if (p.type === 'wide') { setPaddleWidth(PADDLE_W0 * 1.6); paddleWideTimer = 600; }
        else { lives++; updateHud(); }
        return false;
      }
      return true;
    });

    // パーティクル
    for (const pt of particles) {
      pt.x += pt.vx; pt.y += pt.vy; pt.vy += 0.08; pt.life -= 0.03;
    }
    particles = particles.filter(pt => pt.life > 0);
  }

  // ---- 描画 ----
  function draw() {
    ctx.clearRect(0, 0, W, H);

    // ブロック
    for (const b of bricks) {
      ctx.globalAlpha = b.hp < b.maxHp ? 0.55 : 1;
      ctx.fillStyle = b.color;
      roundRect(b.x, b.y, b.w, b.h, 3);
      ctx.fillStyle = 'rgba(255,255,255,.25)';
      roundRect(b.x, b.y, b.w, 5, 3);
      ctx.globalAlpha = 1;
    }

    // パドル
    const grad = ctx.createLinearGradient(0, PADDLE_Y, 0, PADDLE_Y + PADDLE_H);
    grad.addColorStop(0, '#7dd3fc');
    grad.addColorStop(1, '#2563eb');
    ctx.fillStyle = grad;
    roundRect(paddle.x, PADDLE_Y, paddle.w, PADDLE_H, 6);

    // ボール
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, BALL_R, 0, Math.PI * 2);
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#fff';
    ctx.shadowBlur = 12;
    ctx.fill();
    ctx.shadowBlur = 0;

    // パワーアップ
    for (const p of powerups) {
      ctx.fillStyle = p.type === 'wide' ? '#4ade80' : '#f472b6';
      roundRect(p.x - 10, p.y - 7, 20, 14, 4);
      ctx.fillStyle = '#06202e';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(p.type === 'wide' ? 'W' : '+1', p.x, p.y + 3.5);
    }

    // パーティクル
    for (const pt of particles) {
      ctx.globalAlpha = Math.max(0, pt.life);
      ctx.fillStyle = pt.color;
      ctx.fillRect(pt.x - 2, pt.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;

    // 発射待ちヒント
    if (state === 'play' && ball.stuck) {
      ctx.fillStyle = 'rgba(255,255,255,.6)';
      ctx.font = '13px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('スペース / クリックで発射', W / 2, H / 2 + 40);
    }
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.fill();
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  buildBricks();
  resetBall();
  loop();
})();
</script>
</body>
</html>
